{"path":"src/java_module.java","content":"/**
 * Ищет активного пользователя по логину.
 *
 * Метод возвращает {@link Optional}, чтобы явно показать, что пользователь
 * может отсутствовать — это избавляет вызывающий код от проверки на null
 * и делает контракт метода понятным: "нашёл или нет".
 */
public Optional<User> findActive(String login) {
    // Берём поток из коллекции всех пользователей.
    return users.stream()

        // Первый фильтр: совпадение логина без учёта регистра.
        // Используем equalsIgnoreCase, потому что пользователи часто
        // вводят логин с разной раскладкой/регистром (например, "Admin"
        // и "admin"), а логин должен быть уникальным независимо от этого.
        .filter(u -> u.getLogin().equalsIgnoreCase(login))

        // Второй фильтр: пользователь считается активным только если он
        // НЕ заблокирован И срок его действия ещё не истёк.
        // Проверяем isBlocked() коротким замыканием (!u.isBlocked() && ...),
        // чтобы не обращаться к getExpiresAt() для заблокированных
        // пользователей — это защищает от потенциальной NullPointerException,
        // если у заблокированного пользователя expiresAt мог бы быть null.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))

        // Возвращаем первого найденного подходящего пользователя.
        // findFirst() эффективнее findAny() в последовательном потоке,
        // так как останавливает обход сразу после первого совпадения.
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"/// <summary>
/// Универсальный механизм повторных попыток (retry) для асинхронных операций.
/// </summary>
/// <param name="action">Делегат, возвращающий задачу с результатом типа int.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат успешного выполнения действия.</returns>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем попытки от 0 до attempts-1.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить действие и сразу вернуть его результат.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        // Перехватываем только сетевые ошибки (HttpRequestException).
        // Условие "when" гарантирует, что на последней попытке исключение
        // пробрасывается наружу, а не глотается — иначе мы бы зря ждали.
        {
            // Экспоненциальная задержка: 200мс, 400мс, 800мс, ...
            // Это снижает нагрузку на сервер при временных сбоях сети.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Теоретически недостижимая точка: если все попытки исчерпаны,
    // последнее исключение уже было выброшено через фильтр "when".
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// Файл go_module.go реализует простейший «конвейер» обработки задач:
// несколько воркеров читают задачи из общего канала jobs, обрабатывают их
// и отправляют результаты в канал results. Синхронизация завершения всех
// воркеров выполняется через sync.WaitGroup.

import (
	"log"
	"sync"
)

// worker — функция-воркер, которая работает до тех пор, пока не будет
// закрыт входящий канал jobs.
//
// Параметры:
//   - jobs    — канал, по которому воркер получает задачи (Job).
//               Канал только на чтение (<-chan), чтобы гарантировать, что
//               воркер не может случайно отправить в него данные.
//   - results — канал, по которому воркер отправляет успешные результаты
//               (Result). Только на запись (chan<-), аналогично для
//               безопасности интерфейса.
//   - wg      — указатель на WaitGroup, который позволяет вызывающему коду
//               дождаться завершения всех воркеров.
//
// Почему именно так:
// 1. defer wg.Done() ставится сразу после входа в функцию — это защищает
//    от «утечки» счётчика WaitGroup при панике или раннем возврате.
//    Без defer было бы легко забыть вызвать Done() в каком-то из выходов.
//
// 2. Цикл for j := range jobs — идиоматичный способ читать из канала до
//    его закрытия. Как только отправитель закроет jobs, range завершится,
//    и воркер корректно выйдет без дополнительных проверок.
//
// 3. При ошибке обработки мы логируем её и продолжаем работу (continue),
//    а не прерываем весь воркер: одна «плохая» задача не должна останавливать
//    обработку остальных. Если же требуется более сложная стратегия
//    (повторные попытки, мёртвый лоток и т.п.), её можно добавить здесь.
//
// 4. Результат отправляется в results только при успешной обработке.
//    Это упрощает код потребителя: ему не нужно разбирать ошибки,
//    они уже обработаны (записаны в лог) на стороне воркера.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	// Гарантируем, что счётчик WaitGroup будет уменьшен при любом выходе
	// из функции (включая панику).
	defer wg.Done()

	// Читаем задачи из канала, пока он не будет закрыт.
	for j := range jobs {
		// Обрабатываем задачу; process возвращает результат и/или ошибку.
		r, err := process(j)
		if err != nil {
			// Логируем ошибку вместе с идентификатором задачи, чтобы
			// потом можно было найти проблемную задачу в логах.
			log.Printf("job %d: %v", j.ID, err)
			// Пропускаем задачу и переходим к следующей.
			continue
		}
		// Отправляем успешный результат в общий канал результатов.
		results <- r
	}
}
"}

{"path":"src/typescript_module.ts","content":"/**
 * Модуль с утилитами для работы с асинхронными вызовами функций.
 */

/**
 * Создаёт «debounce»-обёртку вокруг переданной функции.
 *
 * Что делает:
 * Возвращает новую функцию, которая при каждом вызове НЕ вызывает `fn` сразу,
 * а откладывает его выполнение на `ms` миллисекунд. Если за это время функция
 * вызывается снова, предыдущий таймер сбрасывается и отсчёт начинается заново.
 * В итоге `fn` выполнится ровно один раз — через `ms` после ПОСЛЕДНЕГО вызова.
 *
 * Почему именно так:
 * 1. Классический паттерн debounce нужен там, где события идут потоком
 *    (например, ввод в поле поиска, ресайз окна, скролл), а дорогая работа
 *    нужна только по факту «тишины». Без него мы бы звали API/пересчитывали
 *    layout на каждое событие и перегружали систему.
 *
 * 2. Обобщение <T extends (...a: any[]) => void> позволяет сохранить точную
 *    сигнатуру исходной функции: параметры и тип возвращаемого значения
 *    вычисляются автоматически через Parameters<T>. Это значит, что вызывающий
 *    код получает корректные подсказки IDE и проверку типов без ручного
 *    дублирования аргументов.
 *
 * 3. Таймер храним в замыкании (`let t`) внутри фабрики, а не снаружи —
 *    каждый вызов debounce() создаёт независимый инстанс со своим состоянием.
 *    Так можно создать несколько несвязанных debounce-функций, и они не будут
 *    мешать друг другу.
 *
 * 4. Тип таймера берём из ReturnType<typeof setTimeout>, а не пишем number:
 *    в Node.js setTimeout возвращает объект Timeout, а в браузере — number.
 *    Такой подход делает код кроссплатформенным без @types/node или DOM-либ.
 *
 * 5. clearTimeout(t) перед назначением нового таймера гарантирует, что
 *    «старый» отложенный вызов точно не сработает — иначе fn мог бы
 *    выполниться дважды (по старому и по новому таймеру).
 *
 * Пример использования:
 *   const onInput = debounce((e: Event) => search(e), 300);
 *   input.addEventListener('input', onInput);
 *
 * @param fn - функция, которую нужно вызывать с задержкой;
 * @param ms - длительность паузы в миллисекундах до реального вызова.
 * @returns обёртка с той же сигнатурой параметров, что и `fn`.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Хранилище идентификатора текущего таймера.
  // Изначально undefined — таймер ещё ни разу не ставился.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем прокси-функцию, принимающую те же аргументы, что и оригинал.
  return (...args: Parameters<T>) => {
    // Если есть незавершённый таймер — отменяем его, чтобы сбросить отсчёт.
    if (t) clearTimeout(t);

    // Ставим новый таймер: через ms мс вызовем fn с последними аргументами.
    t = setTimeout(() => fn(...args), ms);
  };
}
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в хеш-мапу.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"name=John; age=30"` -> `{"name": "john", "age": "30"}`.
///
/// Почему именно так:
/// - Используем итераторы (`split`, `filter_map`, `map`, `collect`), потому что
///   это идиоматичный Rust: код получается кратким, без промежуточных векторов
///   и ручного управления памятью — всё собирается за один проход.
/// - Ключ приводим к нижнему регистру (`to_lowercase`), чтобы разбор был
///   нечувствителен к регистру ключей: "Name" и "name" означают одно и то же.
/// - Значение оставляем как есть (только обрезаем пробелы), сохраняя исходный
///   регистр — для значений он обычно значим.
/// - Пробелы вокруг ключа и значения обрезаются (`trim`), чтобы пользователь
///   мог писать строки с пробелами после разделителей без потери корректности.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // 1. Режем строку по ';' на отдельные пары "ключ=значение".
        .filter_map(|p| p.split_once('=')) // 2. Оставляем только те части, где действительно есть '='.
            // split_once возвращает Option<&(k, v)>: если '=' нет — пара отбрасывается,
            // а не приводит к панике. Это делает парсер устойчивым к мусору во входных данных.
            // Берём split_once вместо splitn/split, потому что нас интересует ровно первое '=',
            // а всё, что после него, остаётся частью значения (в т.ч. дополнительные '=').
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // 3. Нормализуем пару:
            // - k.trim() — убираем пробелы/табы вокруг ключа;
            // - to_lowercase() — унифицируем регистр ключа;
            // - v.trim() — убираем пробелы вокруг значения, но сам текст не меняем.
        .collect() // 4. Собираем все пары в HashMap. Дубликаты ключей: последний выигрывает
            // (это стандартное поведение collect для HashMap).
}
"}
